INSERT OR REPLACE INTO kb_categories VALUES('vision','Cảm giác – Thị giác','Vision','الحواس - البصر','Sens - Vision','👁️',1,'Bot 2 – Sensory Vision: Phần mềm đọc màn hình, kính lúp điện tử, màn hình Braille, OrCam MyEye. Tiêu chuẩn ISO 22.03.06, 22.06.12, 22.36.12; WCAG 2.2; ISO 9241-171.','Bot 2 – Sensory Vision: screen readers, electronic magnifiers, Braille displays, OrCam MyEye. Standards ISO 22.03.06, 22.06.12, 22.36.12; WCAG 2.2; ISO 9241-171.','بوت 2 - الحواس - البصر: قارئات الشاشة والمكبرات الإلكترونية وشاشات برايل. معايير ISO 22.03.06 و WCAG 2.2.','Bot 2 – Sens – Vision : lecteurs d''écran, loupes électroniques, plages Braille. Normes ISO 22.03.06, WCAG 2.2.','https://at.mada.org.qa/technology-category/body-function/sensory-vision/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('hearing','Cảm giác – Thính giác','Hearing','الحواس - السمع','Sens - Audition','👂',2,'Bot 1 – Sensory Hearing: Máy trợ thính (Phonak Lyric, Oticon More), thiết bị cảnh báo Bellman, hệ thống Roger FM. Tiêu chuẩn ISO 22.06.06, 22.09.06, 22.18.03; IEC 60118; ISO 8253-1.','Bot 1 – Sensory Hearing: Hearing aids (Phonak Lyric, Oticon More), Bellman alert devices, Roger FM system. Standards ISO 22.06.06, 22.09.06, 22.18.03; IEC 60118; ISO 8253-1.','بوت 1 - الحواس - السمع: سماعات الأذن وأجهزة التنبيه وأنظمة FM. معايير ISO 22.06.06 و IEC 60118.','Bot 1 – Sens – Audition : aides auditives, dispositifs d''alerte, systèmes FM. Normes ISO 22.06.06, IEC 60118.','https://at.mada.org.qa/technology-category/body-function/sensory-hearing/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('mobility','Vận động thần kinh','Neuromusculoskeletal Movement','العضلات والعصبية','Vouvement neuromusculosquelettique','🦴',3,'Bot 5 – Neuromusculoskeletal Movement: IntegraMouse Plus, Neofect Smart Glove, Bioness L300 Go FES. Tiêu chuẩn ISO 04.24, 06.06, 12.31.03; ISO 10993-1; ISO 13485.','Bot 5 – Neuromusculoskeletal Movement: IntegraMouse Plus, Neofect Smart Glove, Bioness L300 Go FES. Standards ISO 04.24, 06.06, 12.31.03; ISO 10993-1; ISO 13485.','بوت 5 - العضلات والعصبية: فأرة الفم وقفازات إعادة التأهيل. معايير ISO 04.24 و ISO 10993-1.','Bot 5 – Mouvement neuromusculosquelettique : souris buccale, gants de rééducation. Normes ISO 04.24, ISO 10993-1.','https://at.mada.org.qa/technology-category/body-function/neuromusculoskeletal-movement/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('cognition','Tâm thần – Nhận thức','Mental – Cognitive','الإدراكي والمعرفي','Cognitif','🧠',4,'Bot 4 – Mental Cognitive: Hộp chia thuốc Medelert, đồng hồ Time Timer, công cụ WHO GATE cho người sa sút trí tuệ. Tiêu chuẩn ISO 05.06.15, 05.09.03; WHO GATE.','Bot 4 – Mental Cognitive: Medelert pill dispenser, Time Timer, WHO GATE tools for dementia. Standards ISO 05.06.15, 05.09.03; WHO GATE.','بوت 4 - الإدراك والمعرفي: صناديق الأدوية والساعات المرئية. معايير ISO 05.06.15 و WHO GATE.','Bot 4 – Cognitif : piluliers, minuteurs visuels, outils OMS GATE. Normes ISO 05.06.15, OMS GATE.','https://at.mada.org.qa/technology-category/body-function/mental-cognitive/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('communication','Giọng nói và Lời nói','Voice and Speech','الكلام والصوت','Parole et Voix','💬',5,'Bot 3 – Voice and Speech: Tobii Dynavox (SGD điều khiển bằng ánh mắt), Proloquo2Go, hệ thống AAC. Tiêu chuẩn ISO 05.15.06, 05.15.12, 22.21.12; HL7 FHIR v4.','Bot 3 – Voice and Speech: Tobii Dynavox (eye-controlled SGD), Proloquo2Go, AAC systems. Standards ISO 05.15.06, 05.15.12, 22.21.12; HL7 FHIR v4.','بوت 3 - الكلام والصوت: Tobii Dynavox و Proloquo2Go وأنظمة AAC. معايير ISO 05.15.06 و HL7 FHIR v4.','Bot 3 – Parole et Voix : Tobii Dynavox, Proloquo2Go, systèmes CAA. Normes ISO 05.15.06, HL7 FHIR v4.','https://at.mada.org.qa/technology-category/body-function/voice-and-speech/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('daily_living','Di chuyển và Giao thông','Mobility & Transportation','التنقل والحركة','Mobilité et Transport','🦽',6,'Bot 6 – Mobility & Transportation: Scewo Bro (xe lăn leo cầu thang), WeWALK Smart Cane, Quickie Q700-UP M, Rollator Walker. Tiêu chuẩn ISO 12.21.06, 12.21.09, 12.03.06; ISO 7176-19; CE Medical Class II.','Bot 6 – Mobility & Transportation: Scewo Bro (stair-climbing wheelchair), WeWALK Smart Cane, Quickie Q700-UP M, Rollator Walker. Standards ISO 12.21.06, 12.21.09, 12.03.06; ISO 7176-19; CE Medical Class II.','بوت 6 - التنقل والحركة: الكراسي المتحركة الذكية والعصي الذكية. معايير ISO 12.21.06 و ISO 7176-19.','Bot 6 – Mobilité et Transport : fauteuils roulants intelligents, cannes intelligentes. Normes ISO 12.21.06, ISO 7176-19.','https://at.mada.org.qa/technology-category/activities-and-participation/mobility-and-transportation/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('education','Thông tin bổ trợ','Regulatory & Standards','معلومات إضافية ومعايير','Informations supplémentaires et normes','📋',7,'Bot 7 – Regulatory & Standards: Tra cứu ISO 9999:2022, WHO GATE, WCAG 2.2, EU MDR, FDA 21 CFR, CE Mark, HL7 FHIR v4. Cổng thông tin quy định & tiêu chuẩn AT.','Bot 7 – Regulatory & Standards: Lookup ISO 9999:2022, WHO GATE, WCAG 2.2, EU MDR, FDA 21 CFR, CE Mark, HL7 FHIR v4. AT regulations & standards portal.','بوت 7 - المعايير والتنظيمات: بحث ISO 9999:2022 و WHO GATE و WCAG 2.2 و EU MDR.','Bot 7 – Réglementation et Normes : recherche ISO 9999:2022, OMS GATE, WCAG 2.2, EU MDR.','https://at.mada.org.qa/assistive-technology-portal/','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
INSERT OR REPLACE INTO kb_categories VALUES('web_accessibility','Tiếp cận Web','Web Accessibility','إمكانية الوصول للويب','Accessibilité Web','🌐',8,'Công cụ và tiêu chuẩn tiếp cận web (WCAG 2.2, Section 508) – bổ trợ cho Bot 7.','Web accessibility tools and standards (WCAG 2.2, Section 508) – supplementary to Bot 7.','أدوات ومعايير إمكانية الوصول للويب (WCAG 2.2).','Outils et normes d''accessibilité web (WCAG 2.2).','','','2026-10-16T08:07:09.116Z','2026-10-16T08:07:09.116Z');
